CREATE OR REPLACE VIEW `budjettihaukka-gpt.valtiodata.dim_enrichment_join_contract_v1` AS
SELECT *, '1.0.0' AS contract_version
FROM UNNEST([
  STRUCT('recipients_and_grants' AS domain_id, 'grant decision × recipient × payment year' AS target_grain, ['decision_id', 'recipient_business_id', 'payment_year'] AS required_keys, ['granted_eur', 'paid_eur'] AS required_measures, 'Tutkiavustuksia / Valtiokonttori' AS preferred_source, 'Liitä budjettihierarkiaan vain lähteen eksplisiittisellä momenttikoodilla. Nimi- tai tekstiosumaa ei saa käyttää rahamäärän automaattiseen kohdistamiseen.' AS join_rule_fi, 'Saajan tunniste, päätös, euromäärä, vuosi ja lähde-URL on oltava saatavilla.' AS publication_gate_fi, 'interface_only' AS status),
  STRUCT('procurement' AS domain_id, 'contract or procurement notice × supplier' AS target_grain, ['procurement_id', 'buyer_business_id', 'supplier_business_id'] AS required_keys, ['contract_value_eur'] AS required_measures, 'Hilma and Hansel open data' AS preferred_source, 'CPV-koodi ei ole budjettimomentti. Liitä momenttiin vain hankintayksikön julkaisemalla kirjanpito- tai talousarviotunnisteella tai erillisellä auditoidulla siltataululla.' AS join_rule_fi, 'Päällekkäiset ilmoitukset ja puuttuvat sopimusarvot on profiloitava ennen summausta.' AS publication_gate_fi, 'interface_only' AS status),
  STRUCT('outputs_and_outcomes' AS domain_id, 'indicator × organization × reporting period' AS target_grain, ['indicator_id', 'organization_id', 'period'] AS required_keys, ['indicator_value'] AS required_measures, 'agency performance agreements and official sector statistics' AS preferred_source, 'Rahamäärä ja tulosindikaattori pidetään eri faktoina. Liitos tehdään organisaation ja ajanjakson kautta, eikä korrelaatiota nimetä vaikuttavuudeksi.' AS join_rule_fi, 'Mittarin määritelmä, yksikkö, suunta, tavoitearvo ja katkokset on dokumentoitava.' AS publication_gate_fi, 'interface_only' AS status),
  STRUCT('audited_final_accounts' AS domain_id, 'fiscal year × accounting basis × fiscal side' AS target_grain, ['fiscal_year', 'accounting_basis', 'fiscal_side'] AS required_keys, ['official_total_eur'] AS required_measures, 'Valtion tilinpäätös / Valtiokonttori' AS preferred_source, 'Täsmäytä vain sama laskentaperusta ja rajaus. Säilytä sekä mart-summa, virallinen summa, euromääräinen erotus että suhteellinen erotus.' AS join_rule_fi, 'Virallinen lähde-URL, julkaisupäivä, tarkastusstatus ja täsmäytyspoikkeama vaaditaan.' AS publication_gate_fi, 'interface_only' AS status)
])
